#!/usr/bin/env python3
from pathlib import Path

ROOT = Path.cwd()
trace = ROOT / "06-fitness-function/generators/generate_traceability_graph.py"
topo = ROOT / "06-fitness-function/generators/generate_engine_topography.py"
test = ROOT / "06-fitness-function/tests/generators/test_generator_determinism.py"

for path in (trace, topo):
    if not path.exists():
        raise SystemExit(f"Run from repo root; missing: {path}")

trace.write_text('import glob\nimport os\nfrom pathlib import Path\n\nimport yaml\n\n\ndef parse_metadata(filepath):\n    try:\n        with open(filepath, "r", encoding="utf-8") as f:\n            content = f.read()\n        parts = content.split("---")\n        if len(parts) >= 3:\n            meta = yaml.safe_load(parts[1])\n            if meta and "doc_meta" in meta:\n                return meta["doc_meta"]\n    except Exception:\n        pass\n    return None\n\n\ndef _path_key(path: str, base_dir: str) -> str:\n    return Path(path).resolve().relative_to(Path(base_dir).resolve()).as_posix().casefold()\n\n\ndef discover_markdown_files(base_dir: str) -> list[str]:\n    files = glob.glob(os.path.join(base_dir, "**/*.md"), recursive=True)\n    return sorted(files, key=lambda path: _path_key(path, base_dir))\n\n\ndef _sorted_docs(docs: dict, artifact_type: str) -> list[dict]:\n    return sorted(\n        (doc for doc in docs.values() if doc["type"] == artifact_type),\n        key=lambda doc: doc["id"],\n    )\n\n\ndef _parents(value) -> list[str]:\n    if not value:\n        return []\n    if isinstance(value, list):\n        return sorted(value)\n    return [value]\n\n\ndef render_graph(docs: dict) -> str:\n    out = [\n        "```mermaid\\n%%{init: {\'theme\': \'neutral\'}}%%",\n        "graph LR",\n        "    %% EAD Layer",\n    ]\n\n    for d in _sorted_docs(docs, "EAD"):\n        out.append(f"    {d[\'id\']}[{d[\'id\']}]:::ead")\n\n    out.append("    %% PAD Layer")\n    for d in _sorted_docs(docs, "PAD"):\n        out.append(f"    {d[\'id\']}[{d[\'id\']}]:::pad")\n        for parent in _parents(d.get("realizes_capability")):\n            out.append(f"    {d[\'id\']} -.realizes.-> {parent}")\n\n    out.append("    %% SAD Layer")\n    for d in _sorted_docs(docs, "SAD"):\n        out.append(f"    {d[\'id\']}[{d[\'id\']}]:::sad")\n        for parent in _parents(d.get("parent_pad")):\n            out.append(f"    {d[\'id\']} --> {parent}")\n\n    out.extend(\n        [\n            "    classDef ead fill:#059669,stroke:#047857,color:#fff",\n            "    classDef pad fill:#2563eb,stroke:#1d4ed8,color:#fff",\n            "    classDef sad fill:#7c3aed,stroke:#6d28d9,color:#fff",\n            "```",\n        ]\n    )\n    return "\\n".join(out)\n\n\ndef generate_graph():\n    base_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))\n\n    docs = {}\n    for f in discover_markdown_files(base_dir):\n        normalized = Path(f).as_posix()\n        if (\n            "/templates/" in normalized\n            or "/scripts/" in normalized\n            or Path(f).name == "README.md"\n            or Path(f).name == "INDEX.md"\n        ):\n            continue\n\n        meta = parse_metadata(f)\n        if meta and "id" in meta:\n            doc_id = meta["id"]\n            docs[doc_id] = {\n                "id": doc_id,\n                "type": doc_id.split("-")[0],\n                "parent_pad": meta.get("parent_pad"),\n                "realizes_capability": meta.get("realizes_capability"),\n                "governed_by": meta.get("governed_by", []),\n            }\n\n    output_path = os.path.join(base_dir, "03-domain", "TRACEABILITY.md")\n    with open(output_path, "w", encoding="utf-8") as f:\n        f.write("# Architecture Traceability Graph\\n\\n")\n        f.write(render_graph(docs) + "\\n")\n\n    print(f"[OK] Generated Traceability Graph -> {output_path}")\n\n\nif __name__ == "__main__":\n    generate_graph()\n', encoding="utf-8", newline="\n")
topo.write_text('import os\nimport re\nimport subprocess\n\nROOT_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))\nTARGET_FILE = os.path.join(ROOT_DIR, "00-governance", "GDC-001-fitness-functions.md")\n\nCOMMENTS = {\n    "auditors": "# (External environment validators)",\n    "config": "# (Engine configuration & environment variables)",\n    "fs": "# (File system utilities & workspace traversal)",\n    "parsing": "# (Data extraction from raw files)",\n    "reporting": "# (CLI output formatting & CI/CD error logs)",\n    "validators": "# (The core policy sandbox)",\n    "domains": "# (Federated domain-specific triad scripts)",\n    "global_rules.py": "# (Foundational Python rules for all documents)",\n    "cli.py": "# (The Master Fitness Function Entrypoint)",\n    "engine": "# (Core automated execution logic)",\n    "generators": "# (Dynamic docs and topography autobuilders)",\n    "scripts": "# (Git hooks and manual CI/CD utilities)",\n    "tests": "# (High-coverage pytest suite)",\n}\n\n\ndef tracked_paths() -> list[tuple[str, ...]]:\n    result = subprocess.run(\n        ["git", "-C", ROOT_DIR, "ls-files", "--cached", "--", "06-fitness-function"],\n        check=True,\n        capture_output=True,\n        text=True,\n    )\n\n    prefix = "06-fitness-function/"\n    paths = []\n    for raw in result.stdout.splitlines():\n        normalized = raw.replace("\\\\", "/")\n        if not normalized.startswith(prefix):\n            continue\n\n        parts = tuple(part for part in normalized[len(prefix):].split("/") if part)\n        if not parts:\n            continue\n        if parts[-1] == "__init__.py":\n            continue\n        if any(\n            part.startswith(".")\n            or part == "__pycache__"\n            or part.endswith(".egg-info")\n            for part in parts\n        ):\n            continue\n        paths.append(parts)\n\n    return sorted(\n        set(paths),\n        key=lambda parts: tuple(part.casefold() for part in parts),\n    )\n\n\ndef build_path_tree(paths: list[tuple[str, ...]]) -> dict:\n    tree = {}\n    for parts in paths:\n        node = tree\n        for part in parts:\n            node = node.setdefault(part, {})\n    return tree\n\n\ndef render_tree(tree: dict, prefix: str = "") -> list[str]:\n    lines = []\n    items = sorted(tree.items(), key=lambda item: item[0].casefold())\n\n    for idx, (item, children) in enumerate(items):\n        is_last = idx == len(items) - 1\n        connector = "└── " if is_last else "├── "\n        is_dir = bool(children)\n        comment = COMMENTS.get(item, "")\n\n        base_str = (\n            f"{prefix}{connector}{item}/"\n            if is_dir\n            else f"{prefix}{connector}{item}"\n        )\n\n        if comment:\n            clean_len = len(\n                base_str.replace("│", "")\n                .replace("├", "")\n                .replace("─", "")\n                .replace("└", "")\n            )\n            pad = max(1, 26 - clean_len)\n            lines.append(f"│   {base_str}{\' \' * pad}{comment}")\n        else:\n            lines.append(f"│   {base_str}")\n\n        if is_dir:\n            extension = "    " if is_last else "│   "\n            lines.extend(render_tree(children, prefix + extension))\n\n    return lines\n\n\ndef generate_markdown_from_paths(paths: list[tuple[str, ...]]) -> str:\n    tree_lines = ["```text", "scnehaux-architecture/", "└── 06-fitness-function/"]\n    tree_lines.extend(render_tree(build_path_tree(paths), "    "))\n    tree_lines.append("```")\n    return "\\n".join(tree_lines)\n\n\ndef generate_markdown() -> str:\n    return generate_markdown_from_paths(tracked_paths())\n\n\ndef update_document():\n    with open(TARGET_FILE, "r", encoding="utf-8") as f:\n        content = f.read()\n\n    new_content = re.sub(\n        r"<!-- BEGIN_ENGINE_TOPOGRAPHY -->.*?<!-- END_ENGINE_TOPOGRAPHY -->",\n        f"<!-- BEGIN_ENGINE_TOPOGRAPHY -->\\n{generate_markdown()}\\n<!-- END_ENGINE_TOPOGRAPHY -->",\n        content,\n        flags=re.DOTALL,\n    )\n\n    with open(TARGET_FILE, "w", encoding="utf-8") as f:\n        f.write(new_content)\n    print("[OK] Generated Engine Topography -> GDC-001-fitness-functions.md")\n\n\nif __name__ == "__main__":\n    update_document()\n', encoding="utf-8", newline="\n")
test.parent.mkdir(parents=True, exist_ok=True)
test.write_text('import importlib.util\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[3]\n\n\ndef load_module(name: str, relative_path: str):\n    path = ROOT / relative_path\n    spec = importlib.util.spec_from_file_location(name, path)\n    module = importlib.util.module_from_spec(spec)\n    assert spec.loader is not None\n    spec.loader.exec_module(module)\n    return module\n\n\ndef test_traceability_render_is_independent_of_discovery_order():\n    module = load_module(\n        "traceability_generator",\n        "06-fitness-function/generators/generate_traceability_graph.py",\n    )\n\n    docs = {\n        "SAD-002": {\n            "id": "SAD-002",\n            "type": "SAD",\n            "parent_pad": "PAD-PLT-002",\n            "realizes_capability": None,\n        },\n        "EAD-002": {\n            "id": "EAD-002",\n            "type": "EAD",\n            "parent_pad": None,\n            "realizes_capability": None,\n        },\n        "PAD-PLT-002": {\n            "id": "PAD-PLT-002",\n            "type": "PAD",\n            "parent_pad": None,\n            "realizes_capability": ["EAD-002", "EAD-001"],\n        },\n        "EAD-001": {\n            "id": "EAD-001",\n            "type": "EAD",\n            "parent_pad": None,\n            "realizes_capability": None,\n        },\n    }\n\n    reversed_docs = dict(reversed(list(docs.items())))\n    assert module.render_graph(docs) == module.render_graph(reversed_docs)\n\n\ndef test_topography_render_is_independent_of_path_order():\n    module = load_module(\n        "topography_generator",\n        "06-fitness-function/generators/generate_engine_topography.py",\n    )\n\n    paths = [\n        ("engine", "reporting", "reporter.py"),\n        ("engine", "cli.py"),\n        ("scripts", "codeowners-validator.py"),\n        ("generators", "generate_traceability_graph.py"),\n    ]\n\n    assert module.generate_markdown_from_paths(paths) == module.generate_markdown_from_paths(\n        list(reversed(paths))\n    )\n\n\ndef test_topography_uses_git_tracked_inputs_not_ambient_workspace():\n    module = load_module(\n        "topography_generator_tracked",\n        "06-fitness-function/generators/generate_engine_topography.py",\n    )\n\n    tracked = module.tracked_paths()\n    flattened = {"/".join(parts) for parts in tracked}\n\n    assert not any("scratch/" in path for path in flattened)\n    assert not any(".egg-info/" in path for path in flattened)\n    assert "engine/reporting/reporter.py" in flattened\n', encoding="utf-8", newline="\n")

print("Patched:")
print(trace)
print(topo)
print(test)
